import sys; from ray import tune; import optax
# Import my SOTA architecture from my storage
sys.path.append('storage/krono')
from krononet_v4_inputnorm import KronoNetV4_InputNorm
# Import Zephyr II's SOTA PPO trainer from THEIR storage
sys.path.append('storage/zephyr/submissions')
from submission_ppo_clip import ppo_training_step

def _define_hyperparameters():
    # Use Zephyr II's best HPs for this test
    return {'learning_rate':tune.choice([3.5e-4]), 'entropy_coef':tune.choice([0.01]), 'value_loss_coef':tune.choice([0.55]), 'cnn_features_1':tune.choice([32]), 'cnn_features_2':tune.choice([64]), 'conv_lstm_features':tune.choice([96]), 'dilation_rate':tune.choice([6]), 'clip_epsilon':tune.choice([0.2]), 'mistake_penalty':tune.choice([1.0]), 'gae_lambda':tune.choice([0.97]), 'num_heads':tune.choice([2]), 'steps':tune.choice([2]), 'value_clip_range': tune.choice([0.2])}

def create_network(hparams):
    return KronoNetV4_InputNorm(**{k:hparams[k] for k in ['cnn_features_1','cnn_features_2','conv_lstm_features','dilation_rate','num_heads','steps']})

# Use Zephyr II's trainer
training_step = ppo_training_step

def create_optimizer(learning_rate:float=4e-4):
    return optax.chain(optax.clip_by_global_norm(1.0), optax.adamw(learning_rate, weight_decay=1e-4))

BASE_SEED = 3028
